const $ = (sel) => document.querySelector(sel);
const inp = $('#inp');
const normEl = $('#norm');
const syllEl = $('#syll');
const ruleEl = $('#rule');
const accEl = $('#acc');
const warnEl = $('#warn');

// --- Utilities: Greek normalization ---
function stripDiacritics(s){
  // Remove combining marks (accents, breathings, iota subscript, diaeresis, etc.)
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function normalizeGreek(s){
  s = (s||'').trim();
  // Normalize final sigma
  s = s.replace(/ς/g,'σ');
  // Keep Greek letters only plus spaces/hyphen/apostrophe
  s = s.replace(/[^\p{Script=Greek}\s\-’']/gu,'');
  // Collapse spaces
  s = s.replace(/\s+/g,' ');
  return s;
}

function isGreekUpper(ch){
  return ch === ch.toUpperCase() && ch !== ch.toLowerCase();
}

// --- Syllabification (rough) ---
const vowels = new Set(['α','ε','η','ι','ο','υ','ω']);
const diphthongs = new Set([
  'αι','ει','οι','υι','αυ','ευ','ηυ','ου','ωι','ηι','αι','ει'
]);

function isVowel(ch){ return vowels.has(ch); }

function syllabify(word){
  // Very rough: build nuclei as vowel or diphthong; attach preceding consonants to current syllable.
  const w = stripDiacritics(word.toLowerCase());
  let i=0;
  const syll=[];
  let onset='';
  while(i<w.length){
    const ch = w[i];
    if(!isVowel(ch)){
      onset += word[i];
      i++;
      continue;
    }
    // vowel nucleus
    let nucleus = word[i];
    let nucleusPlain = w[i];
    if(i+1<w.length){
      const pairPlain = w.slice(i,i+2);
      if(diphthongs.has(pairPlain)){
        nucleus = word.slice(i,i+2);
        nucleusPlain = pairPlain;
        i += 2;
      } else {
        i += 1;
      }
    } else {
      i += 1;
    }
    syll.push(onset + nucleus);
    onset='';
  }
  if(onset){
    // trailing consonants: tack onto last syllable if any
    if(syll.length) syll[syll.length-1] += onset;
    else syll.push(onset);
  }
  return syll;
}

// --- Accent placement ---
function accentVowelInSyllable(syllable, accentType){
  // accentType: 'acute' | 'circ'
  // Place on last vowel of syllable nucleus (prefer second of diphthong for ει/αι/οι/ου etc.)
  const mapAcute = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  const mapCirc = {
    'α':'ᾶ','η':'ῆ','ι':'ῖ','υ':'ῦ','ω':'ῶ',
    'Α':'ᾶ','Η':'ῆ','Ι':'ῖ','Υ':'ῦ','Ω':'ῶ'
  };
  // For circumflex, only long vowels/diphthongs; we still apply as a toy.
  const chars = Array.from(syllable);
  // Find vowel positions
  const plain = stripDiacritics(syllable);
  const plainChars = Array.from(plain);
  let vpos=[];
  for(let i=0;i<plainChars.length;i++){
    if(isVowel(plainChars[i].toLowerCase())) vpos.push(i);
  }
  if(!vpos.length) return syllable;
  // choose last vowel in syllable
  const idx = vpos[vpos.length-1];
  const ch = chars[idx];
  const base = stripDiacritics(ch);
  const isUpper = isGreekUpper(base);
  const key = isUpper ? base.toUpperCase() : base.toLowerCase();
  let repl = ch;
  if(accentType==='acute') repl = mapAcute[key] || ch;
  if(accentType==='circ') repl = mapCirc[key] || (mapAcute[key] || ch);
  chars[idx] = repl;
  return chars.join('');
}

function applyAccent(word, target){
  // target: {pos:'antepenult'|'penult'|'ultima', type:'acute'|'circ'}
  const syll = syllabify(word);
  if(syll.length===0) return {syll, out: word};
  let idx = syll.length-1;
  if(target.pos==='penult') idx = Math.max(0, syll.length-2);
  if(target.pos==='antepenult') idx = Math.max(0, syll.length-3);
  const outSyll = syll.map((s,i)=> i===idx ? accentVowelInSyllable(s, target.type) : s);
  return {syll, out: outSyll.join('')};
}

// --- Herodian-ish rule guesser ---
const exceptions = new Map([
  // explicit from passage
  ['παιδειος', {pos:'penult', type:'circ', label:'Exception: παιδεῖος (circumflex on penult)'}],
  ['αρνειος', {pos:'ultima', type:'acute', label:'Often treated as oxytone in the passage’s discussion (ἀρνειός)'}],
  ['αφνειος', {pos:'ultima', type:'acute', label:'Exception: ἀφνειός (oxytone)'}],
  ['αρνειος#circ', {pos:'penult', type:'circ', label:'Proper name: Ἀρνεῖος (circumflex on penult)'}],
  ['δαρειος', {pos:'penult', type:'circ', label:'Proper name: Δαρεῖος (circumflex on penult)'}],
  // river/proper names mentioned
  ['σπερχειος', {pos:'ultima', type:'acute', label:'River/proper name pattern: Σπερχειός (oxytone)'}],
  ['αλφειος', {pos:'ultima', type:'acute', label:'River name pattern: Ἀλφειός (oxytone)'}],
  ['πηνειος', {pos:'ultima', type:'acute', label:'River name pattern: Πηνειός (oxytone)'}],
  ['κητειος', {pos:'ultima', type:'acute', label:'River name pattern: Κητειός (oxytone)'}],
  ['ολμειος', {pos:'ultima', type:'acute', label:'Proper name pattern: Ὀλμειός (oxytone)'}],
  ['ορνειος', {pos:'ultima', type:'acute', label:'Proper name pattern: Ὀρνειός (oxytone)'}],
  ['σπονδειος', {pos:'ultima', type:'acute', label:'Proper name pattern: Σπονδειός (oxytone)'}],
  ['αζειος', {pos:'ultima', type:'acute', label:'Ethnic/proper name pattern: Ἀζειός (oxytone)'}],
]);

function looksLikeProperName(original){
  // crude: initial capital Greek letter
  const t = original.trim();
  if(!t) return false;
  const first = Array.from(t)[0];
  return isGreekUpper(first);
}

function hasImpureAlphaCluster(wordPlain){
  // mimic: first syllable has α not "pure" with two consonants following (e.g. ανδ-, αργ-, καδμ-, βακχ-)
  // We'll check: starts with α + two consonants before next vowel.
  const w = wordPlain;
  if(!w.startsWith('α')) return false;
  // find next vowel after initial α
  for(let i=1;i<Math.min(w.length,6);i++){
    if(isVowel(w[i])) return false; // vowel too early => not two-consonant cluster
    // if we have seen two consonants and next is vowel, accept
    if(i>=2 && i+1<w.length && isVowel(w[i+1])) return true;
  }
  return false;
}

function guessRule(original){
  const cleaned = normalizeGreek(original);
  const plain = stripDiacritics(cleaned).toLowerCase();
  const plainNoSpace = plain.replace(/\s+/g,'');

  if(!plainNoSpace) return {ok:false, msg:'Type a Greek word first.'};
  if(!plainNoSpace.endsWith('ειος')){
    return {ok:false, msg:"This toy is for words ending in -ειος."};
  }

  // Special: if user typed capitalized Αρνειος, treat as proper name and use circumflex penult.
  if(plainNoSpace==='αρνειος' && looksLikeProperName(cleaned)){
    return {ok:true, target: exceptions.get('αρνειος#circ'), why: exceptions.get('αρνειος#circ').label};
  }

  if(exceptions.has(plainNoSpace)){
    const ex = exceptions.get(plainNoSpace);
    return {ok:true, target: ex, why: ex.label};
  }

  const syll = syllabify(cleaned);
  const trisyll = syll.length===3;

  // Rule: proper names / rivers => oxytone (acute on ultima)
  if(looksLikeProperName(cleaned)){
    return {ok:true, target:{pos:'ultima', type:'acute'}, why:'Heuristic: looks like a proper name (capitalized) → oxytone (ultima).'};
  }

  // Rule: impure alpha + two consonants => circumflex on penult
  if(hasImpureAlphaCluster(plainNoSpace)){
    return {ok:true, target:{pos:'penult', type:'circ'}, why:"Heuristic: initial α + consonant cluster → penult circumflex (ἀνδρεῖος-type)."};
  }

  // Rule: local-sense words (toy list) often circumflex penult in practice, but passage says local-sense are excluded from proparoxytone set.
  const localish = new Set(['οικειος','αστειος','αγρειος']);
  if(localish.has(plainNoSpace)){
    return {ok:true, target:{pos:'penult', type:'circ'}, why:'Toy choice: “local-sense” set (οἰκεῖος/ἀστεῖος/ἀγρεῖος) → penult circumflex.'};
  }

  // Default Herodian-ish: trisyllabic adjectives in -ειος → antepenult acute
  if(trisyll){
    return {ok:true, target:{pos:'antepenult', type:'acute'}, why:'Default: trisyllabic adjective in -ειος → antepenult acute (proparoxytone).'};
  }

  // Otherwise: fall back to penult acute
  return {ok:true, target:{pos:'penult', type:'acute'}, why:'Fallback: not clearly covered → penult acute.'};
}

function render(){
  const raw = inp.value;
  const cleaned = normalizeGreek(raw);
  const plain = stripDiacritics(cleaned);

  warnEl.textContent = '';

  const g = guessRule(raw);
  if(!g.ok){
    normEl.textContent = cleaned || '—';
    syllEl.textContent = cleaned ? syllabify(cleaned).join(' · ') : '—';
    ruleEl.textContent = g.msg;
    accEl.textContent = '—';
    warnEl.textContent = cleaned && !stripDiacritics(cleaned).toLowerCase().endsWith('ειος') ? 'Tip: try a word ending in -ειος.' : '';
    return;
  }

  const applied = applyAccent(cleaned, g.target);
  normEl.textContent = cleaned || '—';
  syllEl.textContent = applied.syll.join(' · ');
  ruleEl.textContent = g.why;
  accEl.textContent = applied.out;

  // gentle warning if user already had accents
  if(raw !== plain && /[\u0300-\u036fάέήίόύώᾶῆῖῦῶ]/u.test(raw.normalize('NFD'))){
    warnEl.textContent = 'Note: you typed accents/breathings; the toy may overwrite them.';
  }
}

$('#btnGo').addEventListener('click', render);
$('#btnClear').addEventListener('click', ()=>{ inp.value=''; inp.focus(); render(); });
inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });

for(const b of document.querySelectorAll('.chip')){
  b.addEventListener('click', ()=>{ inp.value = b.dataset.w; inp.focus(); render(); });
}

// initial
render();

