function looksLikeProperName(original){
  // crude: initial capital Greek letter
  const t = original.trim();
  if(!t) return false;
  const first = Array.from(t)[0];
  return isGreekUpper(first);
}

function hasImpureAlphaCluster(wordPlain){
  // mimic: first syllable has α not "pure" with two consonants following (e.g. ανδ-, αργ-, καδμ-, βακχ-)
  // We'll check: starts with α + two consonants before next vowel.
  const w = wordPlain;
  if(!w.startsWith('α')) return false;
  // find next vowel after initial α
  for(let i=1;i<Math.min(w.length,6);i++){
    if(isVowel(w[i])) return false; // vowel too early => not two-consonant cluster
    // if we have seen two consonants and next is vowel, accept
    if(i>=2 && i+1<w.length && isVowel(w[i+1])) return true;
  }
  return false;
}

function guessRule(original){
  const cleaned = normalizeGreek(original);
  const plain = stripDiacritics(cleaned).toLowerCase();
  const plainNoSpace = plain.replace(/\s+/g,'');

  if(!plainNoSpace) return {ok:false, msg:'Type a Greek word first.'};
  if(!plainNoSpace.endsWith('ειος')){
    return {ok:false, msg:"This toy is for words ending in -ειος."};
  }

  // Special: if user typed capitalized Αρνειος, treat as proper name and use circumflex penult.
  if(plainNoSpace==='αρνειος' && looksLikeProperName(cleaned)){
    return {ok:true, target: exceptions.get('αρνειος#circ'), why: exceptions.get('αρνειος#circ').label};
  }

  if(exceptions.has(plainNoSpace)){
    const ex = exceptions.get(plainNoSpace);
    return {ok:true, target: ex, why: ex.label};
  }

  const syll = syllabify(cleaned);
  const trisyll = syll.length===3;

  // Rule: proper names / rivers => oxytone (acute on ultima)
  if(looksLikeProperName(cleaned)){
    return {ok:true, target:{pos:'ultima', type:'acute'}, why:'Heuristic: looks like a proper name (capitalized) → oxytone (ultima).'};
  }

  // Rule: impure alpha + two consonants => circumflex on penult
  if(hasImpureAlphaCluster(plainNoSpace)){
    return {ok:true, target:{pos:'penult', type:'circ'}, why:"Heuristic: initial α + consonant cluster → penult circumflex (ἀνδρεῖος-type)."};
  }

  // Rule: local-sense words (toy list) often circumflex penult in practice, but passage says local-sense are excluded from proparoxytone set.
  const localish = new Set(['οικειος','αστειος','αγρειος']);
  if(localish.has(plainNoSpace)){
    return {ok:true, target:{pos:'penult', type:'circ'}, why:'Toy choice: “local-sense” set (οἰκεῖος/ἀστεῖος/ἀγρεῖος) → penult circumflex.'};
  }

  // Default Herodian-ish: trisyllabic adjectives in -ειος → antepenult acute
  if(trisyll){
    return {ok:true, target:{pos:'antepenult', type:'acute'}, why:'Default: trisyllabic adjective in -ειος → antepenult acute (proparoxytone).'};
  }

  // Otherwise: fall back to penult acute
  return {ok:true, target:{pos:'penult', type:'acute'}, why:'Fallback: not clearly covered → penult acute.'};
}

function render(){
  const raw = inp.value;
  const cleaned = normalizeGreek(raw);
  const plain = stripDiacritics(cleaned);

  warnEl.textContent = '';

  const g = guessRule(raw);
  if(!g.ok){
    normEl.textContent = cleaned || '—';
    syllEl.textContent = cleaned ? syllabify(cleaned).join(' · ') : '—';
    ruleEl.textContent = g.msg;
    accEl.textContent = '—';
    warnEl.textContent = cleaned && !stripDiacritics(cleaned).toLowerCase().endsWith('ειος') ? 'Tip: try a word ending in -ειος.' : '';
    return;
  }

  const applied = applyAccent(cleaned, g.target);
  normEl.textContent = cleaned || '—';
  syllEl.textContent = applied.syll.join(' · ');
  ruleEl.textContent = g.why;
  accEl.textContent = applied.out;

  // gentle warning if user already had accents
  if(raw !== plain && /[\u0300-\u036fάέήίόύώᾶῆῖῦῶ]/u.test(raw.normalize('NFD'))){
    warnEl.textContent = 'Note: you typed accents/breathings; the toy may overwrite them.';
  }
}

$('#btnGo').addEventListener('click', render);
$('#btnClear').addEventListener('click', ()=>{ inp.value=''; inp.focus(); render(); });
inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });

for(const b of document.querySelectorAll('.chip')){
  b.addEventListener('click', ()=>{ inp.value = b.dataset.w; inp.focus(); render(); });
}

// initial
render();
